function chunkRecord<T>(
  record: Record<string, T>,
  size: number
): Record<string, T>[] {
  const entries = Object.entries(record);
  const chunks: Record<string, T>[] = [];

  for (let i = 0; i < entries.length; i += size) {
    chunks.push(Object.fromEntries(entries.slice(i, i + size)));
  }

  return chunks;
}

